function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 3 || grid.length > 150) return 'grid needs 3 to 150 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 3 || n > 150) return 'Each row needs 3 to 150 values.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each value is a whole number from 0 to 10^6.';
  }
  return null;
}

