function maxSum(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  let best = 0;

  for (let i = 0; i + 2 < rows; i++) {
    for (let j = 0; j + 2 < cols; j++) {
      const top = grid[i][j] + grid[i][j + 1] + grid[i][j + 2];
      const middle = grid[i + 1][j + 1];
      const bottom = grid[i + 2][j] + grid[i + 2][j + 1] + grid[i + 2][j + 2];
      best = Math.max(best, top + middle + bottom);
    }
  }
  return best;
}

