function maxSum(grid) {
  // Centre every possible hourglass, add the whole 3 x 3 block, then take away the two side cells.
  let answer = -Infinity;
  for (let r = 1; r < grid.length - 1; r++) {
    for (let c = 1; c < grid[0].length - 1; c++) {
      let total = 0;
      for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) total += grid[r + dr][c + dc];
      total -= grid[r][c - 1] + grid[r][c + 1];
      if (total > answer) answer = total;
    }
  }
  return answer;
}

