function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = size === 'large' ? int(90, 100) : int(3, 6);
  const n = size === 'large' ? int(90, 100) : int(3, 6);
  const top = size === 'large' ? 1000000 : (rand() < 0.3 ? 1 : rand() < 0.5 ? 9 : 1000000);
  return [Array.from({ length: m }, () => Array.from({ length: n }, () => int(0, top)))];
}
